import sys
import math
import time
import base64
import pygame  # [web:79][web:83][web:86]
from io import BytesIO
from colorama import init, Fore, Style
import os
import ctypes
import subprocess
import shutil
import platform

init(autoreset=False)

"""
сборка исполняемого файла EXE:
python -m uv run pyinstaller --onefile --console donut_music.py
"""

# ====== ВСТРОЕННАЯ МУЗЫКА (BASE64 WAV) ======
LOOP_WAV_B64 = """

""".strip()
# ============================================

# глобальные параметры бублика
R1 = 1.0
R2 = 2.0
K2 = 8.0
COLOR_PALETTE = [
    Fore.BLUE,
    Fore.CYAN,
    Fore.GREEN,
    Fore.YELLOW,
    Fore.MAGENTA,
    Fore.RED,
    Fore.WHITE,
]
PIXEL_CHAR = "@"


def set_console_title(title: str):
    """Ставит заголовок окна консоли кроссплатформенно (Windows + ANSI)."""
    if platform.system() == "Windows":
        # Unicode‑вариант SetConsoleTitleW [web:156][web:157][web:158]
        ctypes.windll.kernel32.SetConsoleTitleW(title)
    else:
        # ANSI последовательность для *nix‑терминалов [web:158]
        print(f"\033]0;{title}\a", end="", flush=True)


def lock_console_size_and_setup_geometry(target_cols=100, target_lines=30):
    """
    1) Ставит размер окна/буфера через `mode` (без os.system).
    2) Читает фактический размер терминала.
    3) Настраивает глобальные WIDTH, HEIGHT, K1.
    4) Отключает ресайз/максимизацию у консольного окна (WinAPI). [web:138][web:152]
    """
    global WIDTH, HEIGHT, K1

    if os.name != "nt":
        # для не-Windows просто берём текущий размер
        size = shutil.get_terminal_size(fallback=(80, 24))
        WIDTH, HEIGHT = size.columns, size.lines
        WIDTH = max(40, WIDTH - 2)
        HEIGHT = max(20, HEIGHT - 2)
        K1 = WIDTH * K2 * 3 / (8 * (R1 + R2))
        return

    # 1) задаём размер через mode con (subprocess вместо os.system) [web:152]
    cmd = ["cmd", "/c", f"mode con: cols={target_cols} lines={target_lines}"]
    subprocess.run(cmd, shell=False, check=False)

    # 2) узнаём фактический размер окна
    size = shutil.get_terminal_size(fallback=(target_cols, target_lines))
    WIDTH, HEIGHT = size.columns, size.lines
    # чуть уменьшим полезную область, чтобы не упираться в края
    WIDTH = max(40, WIDTH - 2)
    HEIGHT = max(20, HEIGHT - 2)

    # 3) пересчитываем K1 под новые размеры
    K1 = WIDTH * K2 * 3 / (8 * (R1 + R2))

    # 4) отключаем ресайз и кнопку Maximize через WinAPI [web:138][web:144]
    user32 = ctypes.WinDLL("user32", use_last_error=True)
    kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)

    GWL_STYLE = -16
    WS_MAXIMIZEBOX = 0x00010000
    WS_SIZEBOX = 0x00040000  # рамка для изменения размера

    hwnd = kernel32.GetConsoleWindow()
    if not hwnd:
        return

    style = user32.GetWindowLongW(hwnd, GWL_STYLE)
    style &= ~WS_MAXIMIZEBOX
    style &= ~WS_SIZEBOX
    user32.SetWindowLongW(hwnd, GWL_STYLE, style)
    user32.SetWindowPos(
        hwnd,
        None,
        0,
        0,
        0,
        0,
        0x0001 | 0x0002 | 0x0020,  # SWP_NOMOVE | SWP_NOSIZE | SWP_FRAMECHANGED
    )


def luminance_to_color(L: float) -> str:
    L_norm = (L + 1) / 2
    if L_norm < 0:
        L_norm = 0
    if L_norm > 1:
        L_norm = 1
    idx = int(L_norm * (len(COLOR_PALETTE) - 1))
    return COLOR_PALETTE[idx]


def render_frame(A: float, B: float) -> str:
    cosA = math.cos(A)
    sinA = math.sin(A)
    cosB = math.cos(B)
    sinB = math.sin(B)

    output = [" "] * (WIDTH * HEIGHT)
    zbuffer = [-1e9] * (WIDTH * HEIGHT)

    theta_step = 0.04
    phi_step = 0.015

    theta = 0.0
    while theta < 2 * math.pi:
        costheta = math.cos(theta)
        sintheta = math.sin(theta)

        phi = 0.0
        while phi < 2 * math.pi:
            cosphi = math.cos(phi)
            sinphi = math.sin(phi)

            circlex = R2 + R1 * costheta
            circley = R1 * sintheta

            x = circlex * (cosB * cosphi + sinA * sinB * sinphi) - circley * cosA * sinB
            y = circlex * (sinB * cosphi - sinA * cosB * sinphi) + circley * cosA * cosB
            z = K2 + cosA * circlex * sinphi + circley * sinA

            ooz = 1.0 / z

            xp = int(WIDTH / 2 + K1 * ooz * x)
            yp = int(HEIGHT / 2 - K1 * ooz * y)

            L = (
                cosphi * costheta * sinB
                - cosA * costheta * sinphi
                - sinA * sintheta
                - cosB * (cosA * sintheta - costheta * sinA * sinphi)
            )

            if 0 <= xp < WIDTH and 0 <= yp < HEIGHT:
                idx = xp + yp * WIDTH
                if ooz > zbuffer[idx]:
                    zbuffer[idx] = ooz
                    color = luminance_to_color(L)
                    output[idx] = color + PIXEL_CHAR

            phi += phi_step
        theta += theta_step

    lines = []
    for y in range(HEIGHT):
        start = y * WIDTH
        lines.append("".join(output[start : start + WIDTH]))
    return "\n".join(lines) + Style.RESET_ALL


def move_cursor_home():
    sys.stdout.write("\x1b[H")
    sys.stdout.flush()


def start_music_from_embedded():
    # декодируем base64 в байты и создаём file-like объект [web:89][web:95]
    wav_bytes = base64.b64decode(LOOP_WAV_B64)
    wav_file = BytesIO(wav_bytes)

    pygame.mixer.init()
    # pygame.mixer.music умеет читать из обёртки BytesIO как из файла [web:79][web:83][web:96]
    pygame.mixer.music.load(wav_file)
    pygame.mixer.music.play(-1)


def main():
    set_console_title("ДИМА, МЫ ТЕБЯ НЕ ЗАБУДЕМ, И ТЫ НАС ПОМНИ!")
    # сначала фиксируем размер и настраиваем WIDTH/HEIGHT/K1
    lock_console_size_and_setup_geometry(target_cols=100, target_lines=30)

    # запускаем встроенную музыку
    start_music_from_embedded()

    # очистка один раз
    if os.name == "nt":
        subprocess.run(["cmd", "/c", "cls"], shell=False, check=False)
    else:
        subprocess.run(["clear"], shell=False, check=False)

    A = 0.0
    B = 0.0
    try:
        first = True
        while True:
            frame = render_frame(A, B)
            if first:
                print(frame)
                first = False
            else:
                move_cursor_home()
                sys.stdout.write(frame)
                sys.stdout.flush()

            A += 0.03
            B += 0.015
            time.sleep(0.03)
    except KeyboardInterrupt:
        print(Style.RESET_ALL)


if __name__ == "__main__":
    main()
